CREATE TABLE IF NOT EXISTS users(id SERIAL PRIMARY KEY,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN('buyer','exporter','admin')),name TEXT,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS exporters(id SERIAL PRIMARY KEY,user_id INT UNIQUE REFERENCES users(id) ON DELETE CASCADE,company_name TEXT NOT NULL,city TEXT,about TEXT,verified BOOLEAN DEFAULT false);
CREATE TABLE IF NOT EXISTS categories(id SERIAL PRIMARY KEY,name TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS products(id SERIAL PRIMARY KEY,exporter_id INT REFERENCES exporters(id) ON DELETE CASCADE,category_id INT REFERENCES categories(id),name TEXT NOT NULL,description TEXT,moq TEXT,capacity TEXT,origin TEXT,packaging TEXT,image_url TEXT,status TEXT DEFAULT 'active',created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS rfqs(id SERIAL PRIMARY KEY,buyer_id INT REFERENCES users(id),exporter_id INT REFERENCES exporters(id),product_id INT REFERENCES products(id),quantity TEXT NOT NULL,destination TEXT,target_price TEXT,notes TEXT,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS quotations(id SERIAL PRIMARY KEY,rfq_id INT REFERENCES rfqs(id) ON DELETE CASCADE,unit_price TEXT NOT NULL,quantity TEXT NOT NULL,delivery_terms TEXT,valid_until DATE,notes TEXT,status TEXT DEFAULT 'sent',created_at TIMESTAMPTZ DEFAULT now());
INSERT INTO categories(name) VALUES('Sesame Seeds'),('Cashew Nuts'),('Coffee'),('Avocados'),('Tea'),('Chickpeas'),('Pigeon Peas'),('Maize'),('Spices'),('Other') ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS conversations(id SERIAL PRIMARY KEY,buyer_id INT REFERENCES users(id) ON DELETE CASCADE,exporter_id INT REFERENCES exporters(id) ON DELETE CASCADE,created_at TIMESTAMPTZ DEFAULT now(),UNIQUE(buyer_id,exporter_id));
CREATE TABLE IF NOT EXISTS messages(id SERIAL PRIMARY KEY,conversation_id INT REFERENCES conversations(id) ON DELETE CASCADE,sender_id INT REFERENCES users(id),body TEXT NOT NULL,seen BOOLEAN DEFAULT false,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS notifications(id SERIAL PRIMARY KEY,user_id INT REFERENCES users(id) ON DELETE CASCADE,type TEXT,text TEXT NOT NULL,link TEXT,read BOOLEAN DEFAULT false,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS orders(id SERIAL PRIMARY KEY,order_no TEXT UNIQUE,quotation_id INT UNIQUE REFERENCES quotations(id),buyer_id INT REFERENCES users(id),exporter_id INT REFERENCES exporters(id),product_id INT REFERENCES products(id),quantity TEXT,unit_price TEXT,status TEXT DEFAULT 'payment_pending',payment_status TEXT DEFAULT 'awaiting_deposit',created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS reviews(id SERIAL PRIMARY KEY,order_id INT UNIQUE REFERENCES orders(id),buyer_id INT REFERENCES users(id),exporter_id INT REFERENCES exporters(id),rating INT CHECK(rating BETWEEN 1 AND 5),comment TEXT,created_at TIMESTAMPTZ DEFAULT now());
ALTER TABLE quotations ADD COLUMN IF NOT EXISTS total_amount NUMERIC;
ALTER TABLE orders ADD COLUMN IF NOT EXISTS amount NUMERIC;
ALTER TABLE orders ADD COLUMN IF NOT EXISTS currency TEXT DEFAULT 'USD';
ALTER TABLE orders ADD COLUMN IF NOT EXISTS deposit_ref TEXT;
ALTER TABLE orders ADD COLUMN IF NOT EXISTS payout_ref TEXT;
CREATE TABLE IF NOT EXISTS escrow_events(id SERIAL PRIMARY KEY,order_id INT REFERENCES orders(id) ON DELETE CASCADE,event TEXT NOT NULL,actor_id INT REFERENCES users(id),note TEXT,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS disputes(id SERIAL PRIMARY KEY,order_id INT REFERENCES orders(id) ON DELETE CASCADE,buyer_id INT REFERENCES users(id),reason TEXT NOT NULL,details TEXT,status TEXT DEFAULT 'open',decision TEXT,note TEXT,created_at TIMESTAMPTZ DEFAULT now(),resolved_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS ads(id SERIAL PRIMARY KEY,exporter_id INT REFERENCES exporters(id) ON DELETE CASCADE,product_id INT REFERENCES products(id) ON DELETE CASCADE,type TEXT NOT NULL,title TEXT,start_date DATE NOT NULL,end_date DATE NOT NULL,price NUMERIC DEFAULT 0,status TEXT DEFAULT 'pending',created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
INSERT INTO settings(key,value) VALUES('seller_fee_pct','0'),('platform_txn_pct','0.4'),('gateway_fee_pct','0'),('gateway_fee_fixed_tzs','0'),('payout_fee_pct','0'),('payout_fee_fixed_tzs','0'),('fx_markup_pct','1'),('release_mode','manual'),('auto_confirm_days','7') ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS currencies(code TEXT PRIMARY KEY,name TEXT,rate_to_tzs NUMERIC DEFAULT 0,active BOOLEAN DEFAULT false);
