ALTER TABLE orders ALTER COLUMN currency SET DEFAULT 'TZS';
ALTER TABLE orders ADD COLUMN IF NOT EXISTS pay_currency TEXT;
ALTER TABLE orders ADD COLUMN IF NOT EXISTS fx_rate NUMERIC;
ALTER TABLE orders ADD COLUMN IF NOT EXISTS goods_pay NUMERIC;
