ALTER TABLE orders ADD COLUMN IF NOT EXISTS seller_fee NUMERIC;
ALTER TABLE orders ADD COLUMN IF NOT EXISTS payout_fee NUMERIC;
ALTER TABLE orders ADD COLUMN IF NOT EXISTS seller_net NUMERIC;
ALTER TABLE orders ADD COLUMN IF NOT EXISTS platform_earnings_tzs NUMERIC;
ALTER TABLE orders ADD COLUMN IF NOT EXISTS shipped_at TIMESTAMPTZ;
ALTER TABLE messages ADD COLUMN IF NOT EXISTS attachment_url TEXT;
ALTER TABLE messages ADD COLUMN IF NOT EXISTS attachment_name TEXT;
ALTER TABLE messages ADD COLUMN IF NOT EXISTS attachment_type TEXT;
ALTER TABLE orders ADD COLUMN IF NOT EXISTS payment_method TEXT;
ALTER TABLE orders ADD COLUMN IF NOT EXISTS pesapal_tracking_id TEXT;
ALTER TABLE orders ADD COLUMN IF NOT EXISTS pesapal_ref TEXT;
ALTER TABLE users ADD COLUMN IF NOT EXISTS phone TEXT;
ALTER TABLE users ADD COLUMN IF NOT EXISTS country TEXT;
ALTER TABLE users ADD COLUMN IF NOT EXISTS company TEXT;
ALTER TABLE users ADD COLUMN IF NOT EXISTS email_verified BOOLEAN DEFAULT false;
ALTER TABLE users ADD COLUMN IF NOT EXISTS terms_accepted_at TIMESTAMPTZ;
ALTER TABLE users ADD COLUMN IF NOT EXISTS email_token_hash TEXT;
ALTER TABLE users ADD COLUMN IF NOT EXISTS reset_token_hash TEXT;
ALTER TABLE users ADD COLUMN IF NOT EXISTS reset_expires TIMESTAMPTZ;
ALTER TABLE exporters ADD COLUMN IF NOT EXISTS phone TEXT;
ALTER TABLE exporters ADD COLUMN IF NOT EXISTS address TEXT;
ALTER TABLE exporters ADD COLUMN IF NOT EXISTS brela_no TEXT;
ALTER TABLE exporters ADD COLUMN IF NOT EXISTS tin_no TEXT;
ALTER TABLE exporters ADD COLUMN IF NOT EXISTS payout_method TEXT;
ALTER TABLE exporters ADD COLUMN IF NOT EXISTS payout_bank_name TEXT;
ALTER TABLE exporters ADD COLUMN IF NOT EXISTS payout_account_name TEXT;
ALTER TABLE exporters ADD COLUMN IF NOT EXISTS payout_account_no TEXT;
ALTER TABLE exporters ADD COLUMN IF NOT EXISTS verified_until TIMESTAMPTZ;
CREATE TABLE IF NOT EXISTS verifications(id SERIAL PRIMARY KEY,exporter_id INT REFERENCES exporters(id) ON DELETE CASCADE,status TEXT DEFAULT 'submitted',reject_reason TEXT,fee_tzs NUMERIC,payment_method TEXT,payment_ref TEXT,pesapal_tracking_id TEXT,pesapal_ref TEXT,paid_at TIMESTAMPTZ,valid_until TIMESTAMPTZ,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS verification_docs(id SERIAL PRIMARY KEY,verification_id INT REFERENCES verifications(id) ON DELETE CASCADE,doc_type TEXT,public_id TEXT,resource_type TEXT,format TEXT,name TEXT);
